// Validate and extract the keyword from the webhook body
const body = $input.first().json.body || $input.first().json;
const keyword = body.keyword || body.chatInput || body.query;

if (!keyword || keyword.trim() === '' || keyword.includes('{{')) {
  throw new Error('Missing or invalid keyword. Please provide a keyword in the request body as: { "keyword": "your topic here" }');
}

return [{
  json: {
    keyword: keyword.trim(),
    timestamp: new Date().toISOString()
  }
}];

// Parse GPT API response
const response = $input.first().json;

// GPT response format: choices[0].message.content
const rawText = response.choices[0].message.content;

// Clean and parse JSON
const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

let blogData;
try {
  blogData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse AI response as JSON: ' + e.message + ' | Raw: ' + rawText.substring(0, 300));
}

// Validate required fields
const required = ['title', 'meta_description', 'related_keywords', 'headings', 'conclusion', 'cta'];
for (const field of required) {
  if (!blogData[field]) {
    throw new Error('Missing required field: ' + field);
  }
}

// Enforce meta description length
if (blogData.meta_description.length > 160) {
  blogData.meta_description = blogData.meta_description.substring(0, 157) + '...';
}

// Add metadata
blogData.generated_at = new Date().toISOString();
blogData.keyword = $('Validate & Extract Keyword').first().json.keyword;
blogData.status = 'success';

return [{ json: blogData }];

// Build a full HTML blog post from the structured data
const blog = $input.first().json;

let html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${blog.title}</title>
  <meta name="description" content="${blog.meta_description}">
  <meta name="keywords" content="${blog.keyword}, ${(blog.related_keywords || []).join(', ')}">
  <style>
    body { font-family: Georgia, serif; max-width: 800px; margin: 0 auto; padding: 2rem; line-height: 1.8; color: #333; }
    h1 { font-size: 2.2rem; color: #1a1a2e; margin-bottom: 0.5rem; }
    h2 { font-size: 1.6rem; color: #16213e; margin-top: 2.5rem; border-left: 4px solid #0f3460; padding-left: 1rem; }
    h3 { font-size: 1.2rem; color: #0f3460; margin-top: 1.5rem; }
    .meta { color: #666; font-size: 0.9rem; margin-bottom: 2rem; }
    .keywords { background: #f0f4ff; padding: 1rem; border-radius: 8px; margin: 1.5rem 0; }
    .conclusion { background: #f9f9f9; padding: 1.5rem; border-radius: 8px; margin-top: 2rem; border-left: 4px solid #0f3460; }
    .cta { background: #0f3460; color: white; padding: 1.5rem; border-radius: 8px; margin-top: 2rem; text-align: center; font-size: 1.1rem; }
    .links { margin-top: 2rem; }
    .links a { color: #0f3460; }
    ul { padding-left: 1.5rem; }
    li { margin-bottom: 0.5rem; }
  </style>
</head>
<body>
  <h1>${blog.title}</h1>
  <p class="meta">Generated on: ${blog.generated_at} | Keyword: <strong>${blog.keyword}</strong></p>

  <div class="keywords">
    <strong>Related Keywords:</strong> ${(blog.related_keywords || []).join(', ')}
  </div>
`;

for (const section of (blog.headings || [])) {
  html += `  <h2>${section.h2}</h2>\n`;
  if (section.h3 && section.h3.length > 0) {
    for (const sub of section.h3) {
      html += `  <h3>${sub}</h3>\n`;
    }
  }
  const contentHtml = (section.content || '')
    .replace(/\n\n/g, '</p><p>')
    .replace(/\n/g, '<br>');
  html += `  <p>${contentHtml}</p>\n`;
}

html += `
  <div class="conclusion">
    <h2>Conclusion</h2>
    <p>${blog.conclusion}</p>
  </div>

  <div class="cta">
    ${blog.cta}
  </div>
`;

if (blog.links && blog.links.length > 0) {
  html += `
  <div class="links">
    <h3>Further Reading</h3>
    <ul>
`;
  for (const link of blog.links) {
    html += `      <li><a href="${link.url}" target="_blank" rel="noopener">${link.text}</a> (${link.type})</li>\n`;
  }
  html += `    </ul>\n  </div>\n`;
}

html += `</body>\n</html>`;

return [{
  json: {
    ...blog,
    html_output: html
  }
}];

// Handle errors gracefully and return a structured error response
const error = $input.first().json;

return [{
  json: {
    status: 'error',
    message: error.message || 'An unexpected error occurred',
    timestamp: new Date().toISOString()
  }
}];

